local SpongeHolderMaker = {}
local PRODUCTS = {
    iron_spongeholder = { name = "Železni držalo za gobe", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 150, prestige = 4, happiness = 2, description = "Železni držalo za gobe za kopališča." },
    bronze_spongeholder = { name = "Bronast držalo za gobe", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast držalo za gobe za kopališča." },
    silver_spongeholder = { name = "Srebrn držalo za gobe", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn držalo za gobe za kopališča." },
    gilded_spongeholder = { name = "Pozlačen držalo za gobe", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen držalo za gobe za kopališča." },
    jewel_set_spongeholder = { name = "Draguljast držalo za gobe", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast držalo za gobe za kopališča." },
    royal_sovereign_spongeholder = { name = "Kraljevski suveren držalo za gobe", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8800, prestige = 68, happiness = 13, description = "Suveren držalo za gobe z biseri za krono." },
}
local BUILDINGS = {
    spongeholder_workshop = { name = "Spongeholder delavnica", cost = { gold = 325, wood = 185, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
    spongeholder_house = { name = "Spongeholder hiša", cost = { gold = 1185, wood = 370, stone = 265, silver = 7, iron = 7 }, upkeep = 25, qualityBonus = 18 },
    master_spongeholder_atelier = { name = "Mojstrski spongeholder atelje", cost = { gold = 2975, wood = 425, stone = 515, silver = 35, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_spongeholder_palace = { name = "Suverena spongeholder palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
SpongeHolderMaker.ironStock = 12; SpongeHolderMaker.bronzeStock = 10; SpongeHolderMaker.woodStock = 14; SpongeHolderMaker.leatherStock = 12; SpongeHolderMaker.silverStock = 8; SpongeHolderMaker.goldStock = 6; SpongeHolderMaker.jewelStock = 4; SpongeHolderMaker.pearlStock = 4
SpongeHolderMaker.productStock = {}; SpongeHolderMaker.buildings = {}; SpongeHolderMaker.maker = nil; SpongeHolderMaker.activeMaking = {}; SpongeHolderMaker.totalProducts = 0; SpongeHolderMaker.dayTimer = 0
function SpongeHolderMaker.init() SpongeHolderMaker.ironStock=12; SpongeHolderMaker.bronzeStock=10; SpongeHolderMaker.woodStock=14; SpongeHolderMaker.leatherStock=12; SpongeHolderMaker.silverStock=8; SpongeHolderMaker.goldStock=6; SpongeHolderMaker.jewelStock=4; SpongeHolderMaker.pearlStock=4; SpongeHolderMaker.productStock={}; SpongeHolderMaker.buildings={}; SpongeHolderMaker.maker=nil; SpongeHolderMaker.activeMaking={}; SpongeHolderMaker.totalProducts=0; SpongeHolderMaker.dayTimer=0; print("[SpongeHolderMaker] Royal Sponge Holder Maker System initialized (6 products, 4 buildings)") end
function SpongeHolderMaker.hireMaker(n,s) s=s or math.random(55,90); local c=580+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; SpongeHolderMaker.maker={name=n or ("Gobadar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Gobadar najet: %s (spretnost: %d)",SpongeHolderMaker.maker.name,s),"success") end; return true end
function SpongeHolderMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function SpongeHolderMaker.build(id) local ok,e=SpongeHolderMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(SpongeHolderMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function SpongeHolderMaker.getQualityBonus() local b=0; for _,bd in ipairs(SpongeHolderMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function SpongeHolderMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and SpongeHolderMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and SpongeHolderMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and SpongeHolderMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and SpongeHolderMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and SpongeHolderMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and SpongeHolderMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and SpongeHolderMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and SpongeHolderMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #SpongeHolderMaker.buildings==0 then return false,"Potrebna gobadarska delavnica" end; if not SpongeHolderMaker.maker then return false,"Potreben gobadar" end; return true end
function SpongeHolderMaker.make(pt,qty) qty=qty or 1; local ok,e=SpongeHolderMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then SpongeHolderMaker.ironStock=SpongeHolderMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then SpongeHolderMaker.bronzeStock=SpongeHolderMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then SpongeHolderMaker.woodStock=SpongeHolderMaker.woodStock-d.woodCost*qty end; if d.leatherCost then SpongeHolderMaker.leatherStock=SpongeHolderMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then SpongeHolderMaker.silverStock=SpongeHolderMaker.silverStock-d.silverCost*qty end; if d.goldCost then SpongeHolderMaker.goldStock=SpongeHolderMaker.goldStock-d.goldCost*qty end; if d.jewelCost then SpongeHolderMaker.jewelStock=SpongeHolderMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then SpongeHolderMaker.pearlStock=SpongeHolderMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if SpongeHolderMaker.maker then t=math.max(1,t-math.floor(SpongeHolderMaker.maker.skill/13)) end; table.insert(SpongeHolderMaker.activeMaking,{id="spongeholder_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function SpongeHolderMaker.completeMaking(m) local q=1.0+(SpongeHolderMaker.getQualityBonus()/100); if SpongeHolderMaker.maker then q=q+(SpongeHolderMaker.maker.skill/140) end; q=math.min(2.5,q); SpongeHolderMaker.productStock[m.productType]=(SpongeHolderMaker.productStock[m.productType] or 0)+m.quantity; SpongeHolderMaker.totalProducts=SpongeHolderMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if SpongeHolderMaker.maker then SpongeHolderMaker.maker.itemsMade=SpongeHolderMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then SpongeHolderMaker.maker.skill=math.min(100,SpongeHolderMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Držalo izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"spongeholder.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function SpongeHolderMaker.update(dt) if not _G.state then return end; SpongeHolderMaker.dayTimer=SpongeHolderMaker.dayTimer+dt; if SpongeHolderMaker.dayTimer>=30 then SpongeHolderMaker.dayTimer=0; for i=#SpongeHolderMaker.activeMaking,1,-1 do local m=SpongeHolderMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then SpongeHolderMaker.completeMaking(m); table.remove(SpongeHolderMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(SpongeHolderMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if SpongeHolderMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function SpongeHolderMaker.getStats() return {ironStock=SpongeHolderMaker.ironStock,bronzeStock=SpongeHolderMaker.bronzeStock,woodStock=SpongeHolderMaker.woodStock,leatherStock=SpongeHolderMaker.leatherStock,silverStock=SpongeHolderMaker.silverStock,goldStock=SpongeHolderMaker.goldStock,jewelStock=SpongeHolderMaker.jewelStock,pearlStock=SpongeHolderMaker.pearlStock,productStock=SpongeHolderMaker.productStock,numBuildings=#SpongeHolderMaker.buildings,hasMaker=SpongeHolderMaker.maker~=nil,makerName=SpongeHolderMaker.maker and SpongeHolderMaker.maker.name or "—",makerSkill=SpongeHolderMaker.maker and SpongeHolderMaker.maker.skill or 0,activeMaking=#SpongeHolderMaker.activeMaking,totalProducts=SpongeHolderMaker.totalProducts} end
return SpongeHolderMaker
